    Array.prototype.forEach.call(ROOT.querySelectorAll('[data-nav]'), function (el) {
      el.addEventListener('click', function () { collect(s); go(step + Number(el.dataset.nav)); });
    });
    Array.prototype.forEach.call(ROOT.querySelectorAll('[data-k]'), function (el) {
      el.addEventListener('input', function () { collect(s); });
      el.addEventListener('change', function () {
