    .rp-sb-row.is-danger .rp-sb-bar { animation: none; }
  }
</style>
</head>
<body>
<div class="rp-sb" id="rp-sb-root"></div>
<textarea id="rp-sb-raw" hidden>$1</textarea>
<script>
(function () {
  'use strict';

  /* ===== 配置：三处一致性靠这里 ===== */
  var TAG = '状态栏';                 // 与正则 findRegex、frontend-prompt.yaml 的 标签 逐字一致
  var FOLLOW_LATEST = false;          // false=读本楼（每楼快照）；true=永远读最新楼
  var HIDE_UNKNOWN = true;            // 值为 未知 时整条隐去；false 则显示灰条 + 未知

  /* kind: 'text' 进抬头信息条；'bar' 进数值行
     dir:  'up' 值越高越好；'down' 值越高越危险；'none' 不上色
     warn / danger: 危险区起点（按 dir 判断方向），不给就不上色
     range 抄 axis-system.yaml 的对应轴 range */
  var FIELDS = [
    { name: '时间', kind: 'text' },
    { name: '地点', kind: 'text' },
    { name: '灯芯', kind: 'bar', min: 0, max: 100, dir: 'down', warn: 34, danger: 15, unit: '' },
    { name: '潮压', kind: 'bar', min: 0, max: 100, dir: 'up', warn: 60, danger: 82, unit: '', decimals: 0 }
  ];

  var ROOT = document.getElementById('rp-sb-root');
  var NUM_RE = /^-?\d+(?:\.\d+)?$/;

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function pick(block, name) {
    var m = block.match(new RegExp('<' + name + '>([\\s\\S]*?)<\\/' + name + '>'));
    return m ? m[1].trim() : '';
  }

  function parse(text) {
    var m = String(text || '').match(new RegExp('<' + TAG + '>([\\s\\S]*?)<\\/' + TAG + '>'));
    if (!m) return null;
    var out = {};
    FIELDS.forEach(function (f) { out[f.name] = pick(m[1], f.name); });
    return out;
  }

  /* 数据源优先级：$1 注入的隐藏 textarea > getChatMessages。
     有 $1 时没有历史楼层，所以不算差值箭头。 */
  function rawFromDollar1() {
    var el = document.getElementById('rp-sb-raw');
    var v = el ? String(el.value || '').trim() : '';
    if (!v || v.indexOf('$1') === 0) return '';
    return v;
  }

  function messageText() {
    var injected = rawFromDollar1();
    if (injected) return '<' + TAG + '>' + injected + '</' + TAG + '>';
    try {
      var list = getChatMessages(FOLLOW_LATEST ? -1 : getCurrentMessageId());
      return list && list.length ? list[0].message : '';
    } catch (e) { return ''; }
  }

  function previousData() {
    if (rawFromDollar1() || FOLLOW_LATEST || typeof getCurrentMessageId !== 'function') return null;
    try {
      var id = getCurrentMessageId();
      if (id <= 0) return null;
      var prev = getChatMessages(id - 1);
      return prev && prev.length ? parse(prev[0].message) : null;
    } catch (e) { return null; }
  }

  function fmt(n, f) {
    var d = f.decimals == null ? (Math.abs(n) >= 10 || n % 1 === 0 ? 0 : 1) : f.decimals;
    return n.toFixed(d) + (f.unit || '');
  }

  function zone(f, v) {
    if (f.dir === 'none' || f.warn == null) return '';
    if (f.dir === 'down') {
      if (f.danger != null && v <= f.danger) return ' is-danger';
      if (v <= f.warn) return ' is-warn';
      return '';
    }
    if (f.danger != null && v >= f.danger) return ' is-danger';
    if (v >= f.warn) return ' is-warn';
    return '';
  }

  function deltaHtml(f, v, prev) {
    if (!prev || prev[f.name] == null || !NUM_RE.test(prev[f.name])) return '';
    var p = parseFloat(prev[f.name]);
    var d = v - p;
    if (Math.abs(d) < 1e-9) return '';
    var arrow = d > 0 ? '↑' : '↓';
    return '<span class="rp-sb-delta">' + arrow + esc(fmt(Math.abs(d), f)) + '</span>';
  }

  function render() {
    var data = parse(messageText());
    if (!data) { ROOT.innerHTML = ''; return; }

    var prev = previousData();
    var meta = [];
    var rows = [];

    FIELDS.forEach(function (f) {
      var raw = data[f.name];
      if (f.kind === 'text') {
        if (raw) meta.push('<span>' + esc(raw) + '</span>');
        return;
      }
      var known = raw !== '' && NUM_RE.test(raw);
      if (raw === '未知' || raw === '') {
        if (HIDE_UNKNOWN) return;
        rows.push('<div class="rp-sb-row"><span class="rp-sb-name">' + esc(f.name) +
          '</span><div class="rp-sb-bar"><span class="rp-sb-fill" style="width:0"></span></div>' +
          '<span class="rp-sb-val">未知</span></div>');
        return;
      }
      if (!known) {
        rows.push('<div class="rp-sb-row"><span class="rp-sb-name">' + esc(f.name) +
          '</span><div class="rp-sb-bar"><span class="rp-sb-fill" style="width:0"></span></div>' +
          '<span class="rp-sb-val">' + esc(raw) + '</span></div>');
        return;
      }
      var v = parseFloat(raw);
      var span = f.max - f.min || 1;
      var pct = Math.max(0, Math.min(100, ((v - f.min) / span) * 100));
      rows.push('<div class="rp-sb-row' + zone(f, v) + '">' +
        '<span class="rp-sb-name">' + esc(f.name) + '</span>' +
        '<div class="rp-sb-bar"><span class="rp-sb-fill" style="width:' + pct.toFixed(1) + '%"></span></div>' +
        '<span class="rp-sb-val">' + esc(fmt(v, f)) + deltaHtml(f, v, prev) + '</span></div>');
    });

    ROOT.innerHTML =
      (meta.length ? '<div class="rp-sb-meta">' + meta.join('') + '</div>' : '') +
      (rows.length ? '<div class="rp-sb-rows">' + rows.join('') + '</div>' : '');
  }

  render();

  if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, render);
    eventOn(tavern_events.USER_MESSAGE_RENDERED, render);
    if (tavern_events.MESSAGE_SWIPED) eventOn(tavern_events.MESSAGE_SWIPED, render);
    if (tavern_events.MESSAGE_UPDATED) eventOn(tavern_events.MESSAGE_UPDATED, render);
  }
  window.addEventListener('pagehide', function () {
    if (typeof eventClearAll === 'function') eventClearAll();
  });
})();
</script>
</body>
</html>
